/* ===== labs: tiny interactive explorers (no libraries) ===== */
var LAB={};
function labSl(id,l,mn,mx,st,v,u){return '<label class="lsl"><span>'+l+' <b id="'+id+'v">'+v+'</b>'+(u||'')+'</span><input type="range" id="'+id+'" min="'+mn+'" max="'+mx+'" step="'+st+'" value="'+v+'"></label>'}
