function labBind(el,ids,draw){ids.forEach(function(i){var s=el.querySelector('#'+i);s.addEventListener('input',function(){el.querySelector('#'+i+'v').textContent=s.value;draw()})});draw()}
function labV(el,id){return +el.querySelector('#'+id).value}
function labSvg(w,h,b){return '<svg viewBox="0 0 '+w+' '+h+'" class="labsvg" role="img" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+b+'</svg>'}
function labT(x,y,s,a,sz){x=Math.max(16,Math.min(244,x));return '<text x="'+x+'" y="'+y+'" text-anchor="'+(a||'middle')+'" font-size="'+(sz||13)+'" fill="currentColor" stroke="none" font-weight="700">'+s+'</text>'}
LAB.ohm=function(el){el.innerHTML='<div class="lh">Try it: change the battery and the resistor.</div>'+labSvg(260,130,'<rect x="30" y="25" width="200" height="80" rx="14" stroke-opacity=".55"/><rect x="18" y="52" width="24" height="26" fill="var(--surface)"/>'+labT(30,48,'+','middle',12)+'<path d="M24 56h12M24 70h12" /><rect x="206" y="52" width="24" height="26" fill="var(--surface)"/><path d="M212 55l6 4-6 4 6 4-6 4 6 4" stroke="var(--gold)"/><circle id="bulb" cx="130" cy="25" r="14" fill="var(--gold)" fill-opacity="0" stroke="var(--gold)"/><g id="dots"></g>')+'<div class="two">'+labSl('lv','Battery',1,24,1,6,' V')+labSl('lr','Resistor',1,50,1,12,' Ω')+'</div><div class="out" id="lo"></div>';
 var dots=el.querySelector('#dots'),N=14,pos=[];for(var i=0;i<N;i++){pos.push(i/N);dots.insertAdjacentHTML('beforeend','<circle r="3" fill="var(--pri)" stroke="none"></circle>')}
 var cs=dots.children,I=0.5,last=0;function path(t){t=t%1;var L=[200,80,200,80],x,y,d=t*560;if(d<200){x=30+d;y=25}else if(d<280){x=230;y=25+(d-200)}else if(d<480){x=230-(d-280);y=105}else{x=30;y=105-(d-480)}return[x,y]}
 function frame(ts){if(!el.isConnected)return;var dt=Math.min(.05,(ts-last)/1000||0);last=ts;for(var i=0;i<N;i++){pos[i]=(pos[i]+dt*Math.min(1.2,I*.5))%1;var p=path(pos[i]);cs[i].setAttribute('cx',p[0]);cs[i].setAttribute('cy',p[1])}requestAnimationFrame(frame)}
 labBind(el,['lv','lr'],function(){var V=labV(el,'lv'),R=labV(el,'lr');I=V/R;var P=V*I;el.querySelector('#lo').innerHTML='I = V ÷ R = '+V+' ÷ '+R+' = <b>'+(I>=1?I.toFixed(2)+' A':(I*1000).toFixed(0)+' mA')+'</b> · P = <b>'+P.toFixed(1)+' W</b>';el.querySelector('#bulb').setAttribute('fill-opacity',Math.min(.9,P/25))});requestAnimationFrame(frame)};
