 var fw=1;function draw(){el.querySelector('#fw').className='btn sm'+(fw?'':' sec');el.querySelector('#rv').className='btn sm'+(fw?' sec':'');el.querySelector('#led').setAttribute('r',fw?22:0);el.querySelector('#ar').innerHTML=fw?'<path d="M30 40l10 10-10 10" stroke="var(--ok)"/>':'<path d="M70 40l-10 10 10 10" stroke="var(--bad)"/>';el.querySelector('#lo').innerHTML=fw?'<b>Forward bias</b>: current flows from anode (flat side up the triangle) to cathode (bar). About 0.7 V used for silicon.':'<b>Reverse bias</b>: current is blocked. The depletion region grows.'}
