function rColR(z){if(z<12)return [0,0,0,0];var t=[[12,[120,200,255]],[20,[80,170,90]],[30,[40,150,40]],[40,[250,240,50]],[48,[255,150,30]],[55,[230,40,40]],[62,[200,60,200]]],c=t[0][1];for(var i=0;i<t.length;i++)if(z>=t[i][0])c=t[i][1];return [c[0],c[1],c[2],255]}
function rColV(v){var a=Math.min(1,Math.abs(v)/40);if(Math.abs(v)<2)return [150,150,150,255];return v<0?[Math.round(60-40*a),Math.round(180+60*a),Math.round(80-30*a),255]:[Math.round(170+80*a),Math.round(60-40*a),Math.round(60-40*a),255]}
function rColC(c){return c>.95?[230,230,235,255]:c>.85?[250,220,90,255]:c>.7?[255,140,50,255]:c>.55?[130,80,200,255]:[40,60,200,255]}
function radarPaint(s){['rd0','rd1','rd2'].forEach(function(id,pi){var cv=$(id);if(!cv)return;var g=cv.getContext('2d'),im=g.createImageData(150,150);for(var y=0;y<150;y++)for(var x=0;x<150;x++){var f=rField(s.k,x,y,s.k),c=pi===0?rColR(f[0]):pi===1?(f[0]>8?rColV(f[1]):[0,0,0,0]):(f[0]>12?rColC(f[2]):[0,0,0,0]),o=(y*150+x)*4;im.data[o]=c[0];im.data[o+1]=c[1];im.data[o+2]=c[2];im.data[o+3]=c[3]}g.putImageData(im,0,0)})}
stnReg({id:'radar',pack:'met',topic:'torn',notes:'n-torn',title:'Radar signatures',sub:'Reflectivity, velocity, CC',ic:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 12l6-6"/>',
 task:function(){return 'The radar is at the lower-left corner of each panel. Identify the signature, the main hazard and the NWS product you would expect.'},
 gen:function(){return {k:SP(['hook','tvs','debris','bow','fine'])}},
 view:function(s){return '<div class="radar">'+[['rd0','Reflectivity'],['rd1','Velocity'],['rd2','Correlation coefficient']].map(function(p){return '<figure><canvas id="'+p[0]+'" width="150" height="150"></canvas><figcaption>'+p[1]+'</figcaption></figure>'}).join('')+'</div><div class="small mute">Velocity: green = toward the radar, red = away. In CC, rain is high (light gray) and debris is low (blue).</div>'+msel(s,'sig','Signature',RSIG)+msel(s,'hz','Main hazard',RHZ)+msel(s,'pr','NWS product',RPR)},
 after:function(s){radarPaint(s)},
 act:function(s,a,v){s.in[a]=v;return false},
 check:function(s){var A=RANS[s.k],a=s.in,nm=function(L,k){return L.filter(function(x){return x[0]===k})[0][1]},sc=0,L=[];[['sig',RSIG,0],['hz',RHZ,1],['pr',RPR,2]].forEach(function(r){var ok=a[r[0]]===A[r[2]];if(ok)sc+=1/3;L.push([ok,nm(r[1],A[r[2]])])});
  var why={hook:'The reflectivity panel shows rain wrapping around a rotating updraft: a curved <b>hook</b> on the right-rear flank. Velocity shows rotation but it is broad and weak here.',tvs:'Velocity shows a <b>tight inbound-outbound pair</b> (green right next to red). That is intense, small-scale rotation: a tornado vortex signature.',debris:'There is a hook and a tight velocity pair, and the CC panel has a <b>blue hole of low correlation</b> in the hook. Mixed shapes and sizes (debris) lowers CC: a tornado is lofting debris.',bow:'Reflectivity bends into a bow. Velocity shows a broad area of strong outbound (red) flow behind the arc: <b>damaging straight-line wind</b>. Small tornadoes can hide in it.',fine:'A thin, weak line of echo with a green/red wind shift across it is a <b>fine line</b>: an outflow boundary or gust front. It is not a warned storm by itself but storms often form on it.'};
  return {score:sc,lines:L,steps:['Read all three panels together. One panel can mislead.',why[s.k],'Match the hazard: rotation or debris means tornado; a bow means wind; a thin boundary means a wind shift and new storms.','Match the product: tornado signatures lead to a <b>Tornado Warning</b>; bow echoes lead to a <b>Severe Thunderstorm Warning</b>; a fine line alone needs no warning, but watch for new storms.','Remember: toward the radar is negative (green); away is positive (red). Think “red = run away”.']}},
 mats:'a computer or phone with radar.weather.gov or an archived radar case from the NWS, notebook.',
 real:['Open a past severe-weather day on an NWS radar archive (search “NWS radar archive” or the event’s case page).','Look at reflectivity first. Find the hook, bow or thin line. Then switch to velocity and find the strongest green-red pair.','If correlation coefficient is available, look for a low-CC patch inside the hook (a debris ball).','Compare with the warnings and storm reports (spc.noaa.gov) from that day. Did your read match what NWS issued?']});

