var LEDS={red:{vf:1.9,c:'#ff3b3b',n:'Red'},yellow:{vf:2.0,c:'#ffd23f',n:'Yellow'},green:{vf:2.2,c:'#2ee66b',n:'Green'},blue:{vf:3.0,c:'#4aa8ff',n:'Blue'}};
